// WP-9.2 3D Gaussian splatting on Vulkan: see include/fuse/renderer/gsplat/gsplat.hpp.
#include <fuse/renderer/gsplat/gsplat.hpp>

#include <fuse/renderer/compute/gpu_radix_sort.hpp>
#include <fuse/renderer/vk/allocator.hpp>
#include <fuse/renderer/vk/device.hpp>

#include <algorithm>
#include <cstring>

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>

// Generated by cmake/rp_wp92.cmake from shaders/gsplat/*: kGs<Kernel><Slang|Glsl>Spv and
// FUSE_GSPLAT_{SLANG,GLSL} when every kernel of a language exists.
#include "gsplat_spv.h"
#endif

namespace fuse::renderer::gsplat {

namespace {
constexpr u32 kPushBytes = sizeof(GsPush);
constexpr u32 kFrameStride = 256u;
static_assert(sizeof(GsFrameConstants) <= kFrameStride, "frame ring slot");

enum BufferIndex : u32 { kBufSplats = 0, kBufWork, kBufKeys, kBufValues, kBufKeysTemp, kBufValuesTemp, kBufScratch, kBufImage };

u64 align256(u64 v) { return (v + 255u) & ~u64{255u}; }
u32 groupsOf(u32 items, u32 size) { return items == 0u ? 1u : (items + size - 1u) / size; }

BufferUsage usageOf(bool transfer) {
    u32 u = static_cast<u32>(BufferUsage::Storage) | static_cast<u32>(BufferUsage::ShaderDeviceAddress);
    if (transfer) {
        u |= static_cast<u32>(BufferUsage::TransferSrc) | static_cast<u32>(BufferUsage::TransferDst);
    }
    return static_cast<BufferUsage>(u);
}

#if defined(FUSE_VULKAN_BACKEND)
struct Code {
    const u32* words = nullptr;
    usize bytes = 0;
};
template <usize N>
Code code(const u32 (&spv)[N]) {
    return Code{spv, sizeof(spv)};
}
#endif
} // namespace

GsCapabilities queryGsplatCapabilities(const VulkanDevice* device) {
    GsCapabilities c{};
#if defined(FUSE_VULKAN_BACKEND)
    if (device == nullptr || !device->isValid()) {
        return c;
    }
    const RendererCaps& caps = device->info().caps;
    if (!caps.bufferDeviceAddress || !caps.shaderInt64) {
        c.reason = "bufferDeviceAddress / shaderInt64 missing";
        return c;
    }
    c.gsplat = true;
    c.reason = "ok";
#else
    (void)device;
    c.reason = "stub backend";
#endif
    return c;
}

GsplatRenderer::~GsplatRenderer() { destroy(); }

bool GsplatRenderer::createBuffer(Buffer& out, u64 bytes, bool hostVisible, bool transfer, const char* name) {
    BufferDesc d{};
    d.size = static_cast<usize>(std::max<u64>(bytes, 256u));
    d.usage = usageOf(transfer);
    d.memoryUsage = hostVisible ? MemoryUsage::CpuToGpu : MemoryUsage::GpuOnly;
    d.name = name;
    if (!m_desc.allocator->createBuffer(d, out) || out.deviceAddress == 0u || (hostVisible && out.mapped == nullptr)) {
        if (out.handle != nullptr) {
            m_desc.allocator->destroyBuffer(out);
        }
        out = Buffer{};
        return false;
    }
    return true;
}

bool GsplatRenderer::init(const GsplatDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.device == nullptr || desc.allocator == nullptr || desc.bindless == nullptr || desc.framesInFlight == 0u ||
        desc.maxSplats == 0u || desc.maxEntries < 2u) {
        return false;
    }
    if (!queryGsplatCapabilities(desc.device).gsplat) {
        return false;
    }
    GpuRadixSortDesc sortDesc{};
    sortDesc.allocator = desc.allocator;
    sortDesc.debugName = "gsplat.sort";
    std::unique_ptr<GpuRadixSort> sort = GpuRadixSort::create(*desc.device, sortDesc);
    if (sort == nullptr || !sort->isValid() || desc.maxEntries > sort->maxCount(RadixSortKeyType::U64)) {
        return false;
    }
    m_retired.reserve(8);
    m_initialized = true; // destroy() releases partial state from here on
    m_sort = std::move(sort);
    const u64 n = desc.maxSplats;
    const u64 cap = desc.maxEntries;
    m_projectedOffset = 0;
    m_offsetsOffset = align256(n * sizeof(GsProjected));
    m_countersOffset = align256(m_offsetsOffset + n * 4u);
    const u64 workBytes = m_countersOffset + 16u;
    bool ok = createBuffer(m_frameRing, u64{desc.framesInFlight} * kFrameStride, true, false, "gsplat.frame") &&
              createBuffer(m_splats, n * sizeof(GsSplat), true, false, "gsplat.splats") &&
              createBuffer(m_work, workBytes, false, true, "gsplat.work") &&
              createBuffer(m_keys, cap * 8u, false, true, "gsplat.keys") &&
              createBuffer(m_values, cap * 4u, false, true, "gsplat.values") &&
              createBuffer(m_keysTemp, cap * 8u, false, true, "gsplat.keys_temp") &&
              createBuffer(m_valuesTemp, cap * 4u, false, true, "gsplat.values_temp") &&
              createBuffer(m_scratch, GpuRadixSort::scratchBytes(desc.maxEntries), false, true, "gsplat.sort_scratch");
    if (ok) {
        GpuRadixSortBuffers b{};
        b.keys = m_keys.handle;
        b.values = m_values.handle;
        b.keysTemp = m_keysTemp.handle;
        b.valuesTemp = m_valuesTemp.handle;
        b.scratch = m_scratch.handle;
        m_sortBinding = m_sort->bind(b, desc.maxEntries, RadixSortKeyType::U64);
        ok = m_sortBinding != nullptr && m_sortBinding->isValid();
    }
    if (!ok || !createPipelines()) {
        destroy();
        return false;
    }
    return true;
#else
    return false;
#endif
}

void GsplatRenderer::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    collectRetired(~0ull);
    m_sortBinding.reset();
    m_sort.reset();
    if (m_depthSlot.isValid()) {
        m_desc.bindless->unregisterSlot(m_depthSlot);
    }
    for (Buffer* b : {&m_splats, &m_work, &m_keys, &m_values, &m_keysTemp, &m_valuesTemp, &m_scratch, &m_image, &m_frameRing}) {
        if (b->handle != nullptr) {
            m_desc.allocator->destroyBuffer(*b);
        }
        *b = Buffer{};
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    for (void*& pipeline : m_pipelines) {
        if (pipeline != nullptr) {
            vkDestroyPipeline(device, static_cast<VkPipeline>(pipeline), nullptr);
            pipeline = nullptr;
        }
    }
    if (m_layoutHandle != nullptr) {
        vkDestroyPipelineLayout(device, static_cast<VkPipelineLayout>(m_layoutHandle), nullptr);
    }
#endif
    m_layoutHandle = nullptr;
    m_retired.clear();
    for (u8& q : m_queues) {
        q = rg::kNoQueue;
    }
    m_depthImage = nullptr;
    m_depthSlot = BindlessSlotHandle{};
    m_depthHandle = 0;
    m_splatCount = m_shDegree = 0;
    m_width = m_height = m_tileCount = 0;
    m_recordCount = 0;
    m_language = "none";
    m_stats = GsStats{};
    m_constants = GsFrameConstants{};
    m_initialized = false;
}

bool GsplatRenderer::createPipelines() {
#if defined(FUSE_VULKAN_BACKEND)
    Code k[kKernelCount]{};
    bool found = false;
#if defined(FUSE_GSPLAT_SLANG)
    if (m_desc.language == GsKernelLanguage::Auto || m_desc.language == GsKernelLanguage::Slang) {
        k[kPreprocess] = code(kGsPreprocessSlangSpv);
        k[kScan] = code(kGsScanSlangSpv);
        k[kEmit] = code(kGsEmitSlangSpv);
        k[kRanges] = code(kGsRangesSlangSpv);
        k[kRaster] = code(kGsRasterSlangSpv);
        m_language = "slang";
        found = true;
    }
#endif
#if defined(FUSE_GSPLAT_GLSL)
    if (!found && (m_desc.language == GsKernelLanguage::Auto || m_desc.language == GsKernelLanguage::Glsl)) {
        k[kPreprocess] = code(kGsPreprocessGlslSpv);
        k[kScan] = code(kGsScanGlslSpv);
        k[kEmit] = code(kGsEmitGlslSpv);
        k[kRanges] = code(kGsRangesGlslSpv);
        k[kRaster] = code(kGsRasterGlslSpv);
        m_language = "glsl";
        found = true;
    }
#endif
    if (!found) {
        return false;
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    VkDescriptorSetLayout setLayout = static_cast<VkDescriptorSetLayout>(m_desc.bindless->layoutHandle());
    VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0, kPushBytes};
    VkPipelineLayoutCreateInfo layoutInfo{};
    layoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    layoutInfo.setLayoutCount = setLayout != VK_NULL_HANDLE ? 1u : 0u;
    layoutInfo.pSetLayouts = &setLayout;
    layoutInfo.pushConstantRangeCount = 1;
    layoutInfo.pPushConstantRanges = &range;
    VkPipelineLayout layout = VK_NULL_HANDLE;
    if (vkCreatePipelineLayout(device, &layoutInfo, nullptr, &layout) != VK_SUCCESS) {
        return false;
    }
    m_layoutHandle = layout;
    const VkPipelineCreateFlags createFlags = static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags());
    for (u32 i = 0; i < kKernelCount; ++i) {
        VkShaderModuleCreateInfo moduleInfo{};
        moduleInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
        moduleInfo.codeSize = k[i].bytes;
        moduleInfo.pCode = k[i].words;
        VkShaderModule module = VK_NULL_HANDLE;
        if (vkCreateShaderModule(device, &moduleInfo, nullptr, &module) != VK_SUCCESS) {
            return false;
        }
        VkComputePipelineCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
        info.flags = createFlags;
        info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
        info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
        info.stage.module = module;
        info.stage.pName = "main";
        info.layout = layout;
        VkPipeline pipeline = VK_NULL_HANDLE;
        const VkResult result = vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
        vkDestroyShaderModule(device, module, nullptr);
        m_pipelines[i] = pipeline;
        if (result != VK_SUCCESS) {
            return false;
        }
    }
    return true;
#else
    return false;
#endif
}

bool GsplatRenderer::setSplats(const GsSplat* splats, u32 count, u32 shDegree) {
    if (!m_initialized || count > m_desc.maxSplats || (count > 0u && splats == nullptr)) {
        return false;
    }
    if (count > 0u) {
        std::memcpy(m_splats.mapped, splats, static_cast<usize>(count) * sizeof(GsSplat));
    }
    m_splatCount = count;
    m_shDegree = std::min(shDegree, kGsMaxShDegree);
    return true;
}

bool GsplatRenderer::createImageBuffer(u32 width, u32 height, u32 tileCount) {
    const u64 rangesBytes = align256(u64{tileCount} * 8u);
    Buffer fresh{};
    if (!createBuffer(fresh, rangesBytes + u64{width} * height * 16u, false, true, "gsplat.image")) {
        return false;
    }
    if (m_image.handle != nullptr) {
        Retired old{};
        old.buffer = m_image;
        retire(old);
    }
    m_image = fresh;
    m_queues[kBufImage] = rg::kNoQueue;
    m_outputOffset = rangesBytes;
    ++m_stats.imageRebuilds;
    return true;
}

bool GsplatRenderer::bindDepth(const Texture* depth) {
    void* handle = depth != nullptr ? depth->image : nullptr;
    if (handle == m_depthImage && (handle == nullptr || m_depthSlot.isValid())) {
        return true;
    }
    if (m_depthSlot.isValid()) {
        Retired old{};
        old.slot = m_depthSlot;
        retire(old);
    }
    m_depthSlot = BindlessSlotHandle{};
    m_depthImage = nullptr;
    m_depthHandle = 0;
    if (handle == nullptr) {
        return true;
    }
    m_depthSlot = m_desc.bindless->registerTextureSlot(*depth, false);
    if (!m_depthSlot.isValid()) {
        return false;
    }
    m_depthImage = handle;
    m_depthHandle = m_desc.bindless->shaderHandle(m_depthSlot);
    ++m_stats.depthBinds;
    return true;
}

void GsplatRenderer::retire(const Retired& r) {
    Retired copy = r;
    copy.serial = m_frameSerial;
    m_retired.push_back(copy);
    ++m_stats.retired;
}

void GsplatRenderer::destroyRetired(Retired& r) {
    if (r.slot.isValid()) {
        m_desc.bindless->unregisterSlot(r.slot);
    }
    if (r.buffer.handle != nullptr) {
        m_desc.allocator->destroyBuffer(r.buffer);
    }
    r = Retired{};
}

u32 GsplatRenderer::collectRetired(u64 completedSerial) {
    u32 collected = 0;
    usize keep = 0;
    for (usize i = 0; i < m_retired.size(); ++i) {
        if (m_retired[i].serial > completedSerial) {
            m_retired[keep++] = m_retired[i];
            continue;
        }
        destroyRetired(m_retired[i]);
        ++collected;
    }
    m_retired.resize(keep);
    m_stats.retired = m_stats.retired >= collected ? m_stats.retired - collected : 0u;
    return collected;
}

bool GsplatRenderer::beginFrame(u64 frameSerial, const GsCamera& camera, const GsSettings& settings, u32 width,
                                u32 height, const Texture* depth) {
    if (!m_initialized) {
        return false;
    }
    if (depth != nullptr && (depth->image == nullptr || depth->desc.width != width || depth->desc.height != height)) {
        return false;
    }
    GsFrameConstants c{};
    if (!gs_resolve_constants(camera, settings, width, height, m_splatCount, m_shDegree, m_desc.maxEntries,
                              depth != nullptr, c)) {
        return false;
    }
    m_frameSerial = frameSerial;
    m_recordCount = 0;
    m_stats.passes = 0;
    if (width != m_width || height != m_height || m_image.handle == nullptr) {
        if (!createImageBuffer(width, height, c.tileCount)) {
            return false;
        }
        m_width = width;
        m_height = height;
        m_tileCount = c.tileCount;
    }
    if (!bindDepth(depth)) {
        return false;
    }
    c.splats = m_splats.deviceAddress;
    c.projected = m_work.deviceAddress + m_projectedOffset;
    c.offsets = m_work.deviceAddress + m_offsetsOffset;
    c.counters = m_work.deviceAddress + m_countersOffset;
    c.keys = m_keys.deviceAddress;
    c.values = m_values.deviceAddress;
    c.ranges = m_image.deviceAddress;
    c.output = m_image.deviceAddress + m_outputOffset;
    c.depthHandle = m_depthHandle;
    m_constants = c;
    m_keyBits = gs_sort_key_bits(c.tileCount);
    m_stats.keyBits = m_keyBits;
    m_stats.sortPasses = GpuRadixSort::passCount(m_keyBits);
    const u32 slot = static_cast<u32>(frameSerial % m_desc.framesInFlight);
    const u64 offset = u64{slot} * kFrameStride;
    std::memcpy(static_cast<u8*>(m_frameRing.mapped) + offset, &c, sizeof(c));
    m_frameAddress = m_frameRing.deviceAddress + offset;
    return true;
}

GsGraphRefs GsplatRenderer::importInto(rg::Graph& graph) {
    GsGraphRefs refs{};
    if (!m_initialized || m_image.handle == nullptr) {
        return refs;
    }
    auto imp = [&](const Buffer& b, u32 index, const char* name) {
        return graph.importBuffer(rg::ImportedBuffer{b.handle, b.desc.size, m_queues[index], &m_queues[index], name});
    };
    refs.splats = imp(m_splats, kBufSplats, "gsplat.splats");
    refs.work = imp(m_work, kBufWork, "gsplat.work");
    refs.keys = imp(m_keys, kBufKeys, "gsplat.keys");
    refs.values = imp(m_values, kBufValues, "gsplat.values");
    refs.keysTemp = imp(m_keysTemp, kBufKeysTemp, "gsplat.keys_temp");
    refs.valuesTemp = imp(m_valuesTemp, kBufValuesTemp, "gsplat.values_temp");
    refs.scratch = imp(m_scratch, kBufScratch, "gsplat.sort_scratch");
    refs.image = imp(m_image, kBufImage, "gsplat.image");
    return refs;
}

GsplatRenderer::PassRecord* GsplatRenderer::nextRecord(u32 kernel, u32 groups) {
    if (m_recordCount >= kMaxPasses) {
        return nullptr;
    }
    PassRecord* r = &m_records[m_recordCount++];
    *r = PassRecord{};
    r->self = this;
    r->kernel = kernel;
    r->groups = groups;
    r->push.frame = m_frameAddress;
    r->push.padKeyHigh = m_tileCount;
    ++m_stats.passes;
    return r;
}

void GsplatRenderer::addPasses(rg::Graph& graph, const GsGraphRefs& refs, rg::TextureRef depth) {
    if (!m_initialized || !refs.work.valid() || !refs.image.valid()) {
        return;
    }
    constexpr u8 kCs = rg::kStageCompute;
    const u32 n = m_splatCount;
    const u32 cap = m_desc.maxEntries;
    if (PassRecord* r = nextRecord(kPreprocess, groupsOf(n, kGsGroup))) {
        graph.addPass("gsplat.preprocess", &GsplatRenderer::recordDispatch, r)
            .use(refs.splats, rg::Access::StorageRead, {}, kCs)
            .use(refs.work, rg::Access::StorageReadWrite, {}, kCs);
    }
    if (PassRecord* r = nextRecord(kScan, 1u)) {
        graph.addPass("gsplat.scan", &GsplatRenderer::recordDispatch, r)
            .use(refs.work, rg::Access::StorageReadWrite, {}, kCs)
            .use(refs.keys, rg::Access::StorageWrite, {}, kCs)
            .use(refs.values, rg::Access::StorageWrite, {}, kCs)
            .use(refs.image, rg::Access::StorageWrite, rg::BufferRange{0, m_outputOffset}, kCs);
    }
    if (PassRecord* r = nextRecord(kEmit, groupsOf(n, kGsGroup))) {
        graph.addPass("gsplat.emit", &GsplatRenderer::recordDispatch, r)
            .use(refs.work, rg::Access::StorageRead, {}, kCs)
            .use(refs.keys, rg::Access::StorageReadWrite, {}, kCs)
            .use(refs.values, rg::Access::StorageReadWrite, {}, kCs);
    }
    if (PassRecord* r = nextRecord(kKernelCount, 1u)) {
        graph.addPass("gsplat.sort", &GsplatRenderer::recordSortPass, r)
            .use(refs.keys, rg::Access::StorageReadWrite, {}, kCs)
            .use(refs.values, rg::Access::StorageReadWrite, {}, kCs)
            .use(refs.keysTemp, rg::Access::StorageReadWrite, {}, kCs)
            .use(refs.valuesTemp, rg::Access::StorageReadWrite, {}, kCs)
            .use(refs.scratch, rg::Access::StorageReadWrite, {}, kCs);
    }
    if (PassRecord* r = nextRecord(kRanges, groupsOf(cap, kGsGroup))) {
        graph.addPass("gsplat.ranges", &GsplatRenderer::recordDispatch, r)
            .use(refs.work, rg::Access::StorageRead, {}, kCs)
            .use(refs.keys, rg::Access::StorageRead, {}, kCs)
            .use(refs.image, rg::Access::StorageReadWrite, rg::BufferRange{0, m_outputOffset}, kCs);
    }
    if (PassRecord* r = nextRecord(kRaster, m_tileCount)) {
        rg::PassBuilder raster = graph.addPass("gsplat.raster", &GsplatRenderer::recordDispatch, r);
        raster.use(refs.work, rg::Access::StorageRead, {}, kCs)
            .use(refs.values, rg::Access::StorageRead, {}, kCs)
            .use(refs.image, rg::Access::StorageRead, rg::BufferRange{0, m_outputOffset}, kCs)
            .use(refs.image, rg::Access::StorageWrite, rg::BufferRange{m_outputOffset, u64{m_width} * m_height * 16u}, kCs);
        if ((m_constants.flags & kGsFlagDepthTest) != 0u && depth.valid()) {
            raster.use(depth, rg::Access::SampledRead, {}, kCs);
        }
    }
}

u64 GsplatRenderer::copyBytes(GsCopySource what) const {
    switch (what) {
    case GsCopySource::Projected: return u64{m_splatCount} * sizeof(GsProjected);
    case GsCopySource::Offsets: return u64{m_splatCount} * 4u;
    case GsCopySource::Counters: return 16u;
    case GsCopySource::Keys: return u64{m_desc.maxEntries} * 8u;
    case GsCopySource::Values: return u64{m_desc.maxEntries} * 4u;
    case GsCopySource::Ranges: return u64{m_tileCount} * 8u;
    case GsCopySource::Output: return u64{m_width} * m_height * 16u;
    }
    return 0u;
}

void GsplatRenderer::addCopy(rg::Graph& graph, const GsGraphRefs& refs, GsCopySource what, rg::BufferRef dst,
                             u64 dstOffset) {
    if (!m_initialized || !dst.valid() || copyBytes(what) == 0u) {
        return;
    }
    PassRecord* r = nextRecord(kKernelCount, 0u);
    if (r == nullptr) {
        return;
    }
    switch (what) {
    case GsCopySource::Projected: r->copyFrom = refs.work; r->copySrc = m_projectedOffset; break;
    case GsCopySource::Offsets: r->copyFrom = refs.work; r->copySrc = m_offsetsOffset; break;
    case GsCopySource::Counters: r->copyFrom = refs.work; r->copySrc = m_countersOffset; break;
    case GsCopySource::Keys: r->copyFrom = refs.keys; break;
    case GsCopySource::Values: r->copyFrom = refs.values; break;
    case GsCopySource::Ranges: r->copyFrom = refs.image; break;
    case GsCopySource::Output: r->copyFrom = refs.image; r->copySrc = m_outputOffset; break;
    }
    r->copyBytes = copyBytes(what);
    r->copyDst = dstOffset;
    r->copyTo = dst;
    graph.addPass("gsplat.copy", &GsplatRenderer::recordCopy, r)
        .use(r->copyFrom, rg::Access::TransferSrc, rg::BufferRange{r->copySrc, r->copyBytes})
        .use(dst, rg::Access::TransferDst, rg::BufferRange{dstOffset, r->copyBytes});
}

void GsplatRenderer::recordDispatch(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    const GsplatRenderer& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(self.m_pipelines[r.kernel]));
    self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, self.m_layoutHandle, 0);
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_layoutHandle), VK_SHADER_STAGE_COMPUTE_BIT, 0,
                       kPushBytes, &r.push);
    vkCmdDispatch(cmd, r.groups, 1u, 1u);
#else
    (void)context;
    (void)user;
#endif
}

void GsplatRenderer::recordSortPass(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    const GsplatRenderer& self = *r.self;
    // The sort is its own render graph recorded inline: its first barrier waits on every earlier command,
    // its passes are declared, and the key width keeps the pass count even (the result ends in keys/values).
    self.m_sort->recordSort(context.commandBuffer, *self.m_sortBinding, self.m_desc.maxEntries, self.m_keyBits, nullptr);
#else
    (void)context;
    (void)user;
#endif
}

void GsplatRenderer::recordCopy(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    const VkBufferCopy region{r.copySrc, r.copyDst, r.copyBytes};
    vkCmdCopyBuffer(cmd, static_cast<VkBuffer>(context.buffer(r.copyFrom)), static_cast<VkBuffer>(context.buffer(r.copyTo)),
                    1, &region);
#else
    (void)context;
    (void)user;
#endif
}

} // namespace fuse::renderer::gsplat
